#include <bits/stdc++.h>using namespace std; int main() {    long long n;    cin >> n;     int c = 0;    while (n > 0) {        int rem = n % 10;        if (rem == 4 || rem == 7) {            c++;        }        n /= 10;    }    if (c == 0) {        cout << "NO";        return 0;    }     while (c > 0) {        int rem = c % 10;        if (rem != 4 && rem != 7) {            cout << "NO";            return 0;        }        c /= 10;    }     cout << "YES";}